  window.Themeasy.PreviewRuntime.register('themeasy-image-reveal', function ($scope, $, api) {
    // The reveal is a one-shot ENTRANCE effect, so it plays on the canvas like
    // every other entrance animation — the user has to see the effect they just
    // picked. The wrapper carries tms-image-reveal--static, which in this module
    // strips only the scroll mechanics: init() then plays the timeline
    // immediately instead of arming a ScrollTrigger. reset() first so switching
    // the effect in the panel replays it.
    if (window.Themeasy.imageReveal && $scope.find('.tms-image-reveal').length) {
      window.Themeasy.imageReveal.reset($scope[0])
      window.Themeasy.imageReveal.init($scope[0])
    }
  })

